SELECT DISTINCT md.chembl_id, cr.compound_name, cs.canonical_smiles FROM docs d JOIN compound_records cr ON cr.doc_id = d.doc_id JOIN molecule_dictionary md ON md.molregno = cr.molregno JOIN compound_structures cs ON cs.molregno = md.molregno WHERE d.chembl_id = 'CHEMBL1123859' AND cs.canonical_smiles IS NOT NULL ORDER BY md.chembl_id ASC, cr.compound_name ASC, cs.canonical_smiles ASC
